using System;using System.Collections.Generic;
namespace LoopPedal {
static class FreezeChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static void Release(List<string> log){for(int mode=1;mode<=2;mode++){var f=new MasterFx{GrainMode=mode,GrainSize=.09f,Cloudy=0,Texture=0,CloudFeedback=0,Spray=0,Spread=0,CloudWindow=.04f};var c=new CloudsFx();float l,r;for(int i=0;i<400000;i++)c.Process(.5f,.5f,f,out l,out r);f.Freeze=true;l=r=0;for(int i=0;i<12000;i++)c.Process(0,0,f,out l,out r);f.Freeze=false;float last=l;double max=0;for(int i=0;i<12000;i++){c.Process(-.5f,-.5f,f,out l,out r);max=Math.Max(max,Math.Abs(l-last));last=l;}Check(max<.005,"Freeze-release discontinuity "+mode+" "+max);log.Add("PASS frozen/live splice mode="+mode+" max sample step="+max);}}
 static void Ranges(List<string> log){var defaults=new MasterFx();foreach(int k in new[]{6,8,15,16,17}){defaults=new MasterFx();float before=FxParameters.Get(defaults,k);FxParameters.Set(defaults,k,FxParameters.Default(defaults,k));Check(Math.Abs(FxParameters.Get(defaults,k)-before)<.00001,"Grain knob reset defaults");FxParameters.Set(defaults,k,1);Check(Math.Abs(FxParameters.Get(defaults,k)-1)<.00001,"Grain max mapping");}FxParameters.Set(defaults,6,1);FxParameters.Set(defaults,8,1);FxParameters.Set(defaults,15,1);Check(defaults.GrainSize==1&&defaults.Spray==4&&defaults.Spread==2,"Extended range endpoints");for(int mode=0;mode<3;mode++)foreach(float size in new[]{.002f,1}){var f=new MasterFx{Grain=1,GrainMode=mode,GrainSize=size,Spray=4,Spread=2,Position=1.5f,GrainPitch=12,GrainReverse=true,Density=12,CloudFeedback=.92f};for(int i=0;i<480000;i++){if(i%48000==0)f.Freeze=!f.Freeze;float l,r,input=(float)(.15*Math.Sin(i*.04));f.Process(input,input,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l)&&Math.Abs(l)<2&&Math.Abs(r)<2,"Extended grain stability");}log.Add("PASS extended grain range, max spray/spread/pitch/density and repeated Freeze mode="+mode+" size="+size);}}
 public static void Run(List<string> log){Release(log);Ranges(log);for(int mode=0;mode<3;mode++){var a=new MasterFx{Grain=1,GrainMode=mode,GrainMix=1,GrainSize=.04f,Position=.04f,Spray=0,CloudWindow=.08f,CloudFeedback=0};var b=new MasterFx{Grain=1};a.CopySharedSettingsTo(b);float al,ar,bl,br;for(int i=0;i<48000;i++){a.Process((float)(.15*Math.Sin(i*.03)),0,out al,out ar);b.Process(0,(float)(.15*Math.Sin(i*.07)),out bl,out br);}a.Freeze=true;a.CopySharedSettingsTo(b);Check(!b.Freeze,"A Freeze leaked into B");double ea=0,eb=0;for(int i=0;i<192000;i++){a.Process(0,0,out al,out ar);b.Process(0,0,out bl,out br);if(i>=144000){ea+=al*al+ar*ar;eb+=bl*bl+br*br;}}Check(ea>.001&&eb<ea*.0001,"Frozen A/live B audio isolation mode="+mode+" "+ea+"/"+eb);for(int i=0;i<48000;i++)b.Process(0,(float)(.15*Math.Sin(i*.09)),out bl,out br);b.Freeze=true;a.Freeze=false;a.CopySharedSettingsTo(b);Check(b.Freeze,"Unfreezing A released B");ea=eb=0;for(int i=0;i<384000;i++){a.Process(0,0,out al,out ar);b.Process(0,0,out bl,out br);if(i>=336000){ea+=al*al+ar*ar;eb+=bl*bl+br*br;}}Check(eb>.001&&ea<eb*.0001,"Live A/frozen B audio isolation mode="+mode+" "+ea+"/"+eb);var export=b.Copy();a.CopySharedSettingsTo(export);Check(export.Freeze,"B export lost Freeze");double copied=0;for(int i=0;i<48000;i++){export.Process(0,0,out bl,out br);copied+=bl*bl+br*br;}Check(copied>.001,"B copied freeze lost captured audio");log.Add("PASS independent A/B Freeze, actual frozen/live audio isolation and B export history, grain type="+mode);}}
}
}
